(function(root){
'use strict';
const P=root.PayPlanner,L=root.LAYERS_DATA,D=root.PAY_DATA,E=root.PayEngine,B=root.PayBenchmarks;
let fx=String(L.fxCADperUSD);
let api,explorer={country:'US',specialty:'Family medicine',basis:'auto',sort:'name',query:''};
const $=id=>document.getElementById(id),esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const number=x=>new Intl.NumberFormat('en-US',{maximumFractionDigits:0}).format(x),money=(x,c)=>Number.isFinite(x)?`${x<0?'−':''}${c==='CA'?'CA':'US'}$${number(Math.abs(x))}`:'—',intl=x=>Number.isFinite(x)?`I$ ${number(x)}`:'—';
const options=(xs,v)=>xs.map(x=>{const [key,label]=Array.isArray(x)?x:[x,x];return `<option value="${esc(key)}"${String(v)===String(key)?' selected':''}>${esc(label)}</option>`;}).join('');
const link=(u,t)=>`<a href="${esc(u)}" target="_blank" rel="noopener noreferrer">${esc(t)}</a>`;
function input(i,key,label,p,help='',max=1e8,min=0){return `<label>${label}<input data-plan-side="${i}" data-plan-key="${key}" type="number" step="any" min="${min}" max="${max}" value="${esc(p[key])}"${p[key]===''?' placeholder="Enter amount"':''}>${help?`<span class="hint">${help}</span>`:''}</label>`;}
function select(i,key,label,p,opts){return `<label>${label}<select data-plan-side="${i}" data-plan-key="${key}">${options(opts,p[key])}</select></label>`;}
function plan(s){if(!s.plan)s.plan=P.defaults();return s.plan;}
function places(s){return s.country==='US'?L.housingUS.filter(x=>x.state===s.place).map(x=>[x.area,x.area]):L.housingCA.filter(x=>x[0]===s.place).map(x=>[x[1],`${x[1]} · ${x[3]==='new-tenant'?'new-tenant mean':'all-unit mean'}`]);}
function housingReference(s,p){if(s.country==='US'){const r=L.housingUS.find(x=>x.state===s.place&&x.area===p.housingArea);return r?{amount:r.rents[Number(p.bedrooms)],note:`HUD FY2025 · ${p.bedrooms==0?'studio':p.bedrooms+' bedrooms'} · ${r.area}${r.revised?' · revised April 2025':''}. Includes major utilities; exclude them from the utilities field.`,url:L.sources[0][1]}:null;}const r=L.housingCA.find(x=>x[0]===s.place&&x[1]===p.housingArea);return r?{amount:r[2],note:`CMHC October 2025 · ${r[1]} · 2-bedroom purpose-built ${r[3]==='new-tenant'?'new-tenant mean':'all-unit mean (can understate a new lease)'}. Check which utilities are included.`,url:L.sources[3][1]}:null;}
function renderForms(){const {scenarios}=api.get();$('planner-inputs').innerHTML=scenarios.map((s,i)=>{
 const p=plan(s),ca=s.country==='CA',ref=housingReference(s,p),itemized=p.budgetMode==='itemized';
 return `<article class="planner-side"><div class="scenario-name"><span class="letter">${i?'B':'A'}</span><h3>${esc(ca?D.provinces[s.place]:s.place)}</h3><span class="currency">${ca?'CAD':'USD'}</span></div>
 ${select(i,'budgetMode','Living costs',p,[['modeled','Comparable lifestyle from the purchasing-power panel'],['itemized','Build my own itemized budget'],['total','Use my entered total living budget']])}
 <p class="hint">${p.budgetMode==='modeled'?'Uses the local purchasing-power model and the editable I$ lifestyle target above. This is an illustrative budget.':p.budgetMode==='total'?'Uses the total monthly living budget under expense and tax details. It replaces itemized costs.':'Food, transport and other amounts start as illustrative local-currency allowances. Review every category. Exclude insurance already deducted from take-home.'}</p>
 ${itemized?`<div class="grid2">${select(i,'housingMode','Housing arrangement',p,[['rent','Rent'],['own','Own a home']])}</div>${p.housingMode==='rent'?`
 <details open><summary>Rent and published housing references</summary><div class="grid2">${input(i,'rent','Rent / month',p)}${select(i,'housingArea',ca?'Canadian city reference':'HUD rent area within this state',p,[['','Choose an area'],...places(s)])}${!ca?select(i,'bedrooms','Bedrooms',p,[[0,'Studio'],[1,'1'],[2,'2'],[3,'3'],[4,'4']]):''}</div>
 ${ref?`<p class="housing-ref"><strong>${money(ref.amount,s.country)} / month</strong> <button data-load-rent="${i}">Use this rent</button></p><p class="hint">${esc(ref.note)} ${link(ref.url,'Source')}</p>`:`<p class="hint">${places(s).length?'Choose an area to inspect a reference, or enter a rental quote.':'No verified city rent is bundled for this province. Enter a quote; a missing reference does not mean free housing.'}</p>`}
 <p class="hint">${esc(p.rentNote)}</p><p class="hint">${ca?'CMHC rents are survey means, not salary benchmarks. New-tenant and all-unit averages describe different groups.':'HUD FMRs estimate the 40th percentile gross rent of standard-quality units. They are an affordable-housing program benchmark, not luxury rents, live listings, or a state median.'} Housing selection does not change your tax residence or purchasing-power index.</p></details>`:`<details open><summary>Home ownership · illustrative financing</summary><div class="grid2">${input(i,'homePrice','Purchase price',p)}${input(i,'downPercent','Down payment (%)',p,'',100)}${input(i,'mortgageRate','Mortgage interest (%)',p,'Illustrative rate; use a lender quote.',50)}${input(i,'mortgageYears','Amortization (years)',p,'Fixed rate held over this period.',50,1)}${input(i,'propertyTax','Property taxes / year',p)}${input(i,'homeInsurance','Home insurance / year',p)}${input(i,'mortgageInsurance','Mortgage insurance / month',p,'0 assumes none; enter required PMI or equivalent.')}${input(i,'maintenance','Maintenance reserve / year',p)}${input(i,'hoa','Condo / HOA fees / month',p)}${input(i,'closingCosts','Closing costs, one time',p)}</div><p class="hint">Includes principal and interest in cash spending. ${ca?'Monthly payments with semiannual interest conversion; actual renewal rates can change.':'Monthly interest compounding.'} Include land-transfer tax and any upfront mortgage-insurance premium in closing costs. This is not loan approval. Enter investments below after any down payment; home equity is excluded from projections.</p></details>`}
 <div class="grid2">${input(i,'food','Food & dining / month',p)}${input(i,'transport','Transport & car costs / month',p)}${input(i,'utilities','Utilities, phone, internet / month',p,'Only amounts not included in rent.')}${input(i,'children','Childcare & school / month',p,'Net of any subsidy; 0 assumes none.')}${input(i,'other','Travel, clothing & other / month',p)}</div>`:''}
 <details><summary>Debt repayment</summary><div class="grid2">${input(i,'debt','Debt balance',p,'No debt assumed until entered.')}${input(i,'debtRate','Annual interest (%)',p,'Illustrative; enter your weighted loan rate.',50)}${input(i,'debtYears','Repayment term (years)',p,'Standard amortization, no forgiveness.',50,1)}${input(i,'debtExtra','Extra payment / month',p)}</div>${!ca?`<p class="hint">AAMC: US$215,000 median education debt among indebted 2025 U.S. medical graduates; 70% reported debt. ${link(L.sources[4][1],'AAMC fact card')} <button data-load-debt="${i}">Use US$215,000 example</button></p>`:''}<p class="hint">This models a fixed-rate amortizing loan. It does not assume PSLF, income-driven repayment, Canadian loan assistance or an interest subsidy. Extra payments may be inappropriate for a forgiveness strategy. Enter debts in the scenario’s currency.</p></details>
 <details><summary>Work hours and household income</summary><div class="grid2">${input(i,'hours','Total work hours / week',p,'Clinical, charting, admin and active call.',120,1)}${input(i,'weeks','Weeks worked / year',p,'Exclude actual weeks off.',52,1)}${input(i,'commute','Commute hours / working week',p,'Tracked separately from work.',40)}${input(i,'partnerNet','Other household take-home / year',p,'Already after its own taxes and costs.')}</div><p class="hint">50 hours × 46 weeks and 4 commute hours are editable examples, not specialty averages. Hours change the hourly comparison; they do not automatically scale salary. Household income is added only to this budget layer.</p></details>
 <details><summary>Savings, investing and moving</summary><div class="grid2">${input(i,'assets','Current financial assets',p,'Cash/investments after any home purchase. Home equity excluded.')}${input(i,'investPercent','Invest share of surplus (%)',p,'Remainder is untracked extra spending.',100)}${input(i,'netReturn','Annual net investment return (%)',p,'Illustrative, after tax and fees; not a forecast.',15,-10)}${input(i,'horizon','Projection years',p,'Income and living costs held fixed.',40,1)}${input(i,'moveCost','One-time move / licensing cost',p,'Deducted in month 1, not every year.')}</div><p class="hint">Nominal scenario arithmetic: no pay growth, inflation, pension, employer match or future tax changes. Debt payments are released into surplus when the loan ends. Deficits draw down assets; a negative asset balance means an unfunded plan.</p></details>
 </article>`;}).join('');}
function ledger(rows,c){return `<dl class="ledger">${rows.map(([k,v])=>`<div><dt>${k}</dt><dd>${money(v,c)}</dd></div>`).join('')}</dl>`;}
function getPlans(){const x=api.get();return x.scenarios.map((s,i)=>P.calculate(s,x.results[i],plan(s),E.localPrice(s),x.lifestyle));}
function renderResults(){const x=api.get(),ps=getPlans();$('planner-results').innerHTML=`<div class="planning-results">${ps.map((r,i)=>{const s=x.scenarios[i],p=plan(s);if(!r.valid)return `<article class="planning-result"><h3>${i?'B':'A'} · Budget incomplete</h3><p>${esc(r.error)}</p></article>`;return `<article class="planning-result"><span class="eyebrow">${i?'B':'A'} · MONTHLY SURPLUS AFTER LIVING COSTS & DEBT</span><div class="plan-amount${r.left<0?' deficit':''}">${money(r.left,s.country)}</div><p class="hint">${r.left>=0?'Available to save, invest or spend beyond the entered budget.':'Spending exceeds the available household cash.'}</p>
 ${ledger([['Household take-home / month',r.household],['Living costs',r.living],['Debt payment this month',r.debt.payment],['Surplus after those costs',r.left],['Average first-year surplus after moving',r.afterMove]],s.country)}
 <div class="metric-pair"><div><span>Cash per work hour</span><strong>${money(r.hourly,s.country)}</strong></div><div><span>Including commute time</span><strong>${money(r.committedHourly,s.country)}</strong></div></div>
 <p class="hint">${number(r.work)} work hours / year. Price-adjusted cash per committed hour: ${intl(r.powerHourly)}. Uses this physician’s take-home; excludes other household income.</p>
 ${r.housing&&p.housingMode==='own'?`<p>Ownership cash costs: <strong>${money(r.housing.monthly,s.country)} / month</strong>. Down payment + entered closing costs: <strong>${money(r.housing.upfront,s.country)}</strong> upfront, funded separately.</p>`:''}
 ${Number(p.debt)>0?`<p>Debt-free in <strong>${(r.debt.months/12).toFixed(1)} years</strong> (${r.debt.months} payments); total interest <strong>${money(r.debt.interest,s.country)}</strong>.</p>`:'<p class="hint">No debt repayment assumed.</p>'}
 <p class="hint">Financial assets cover ${r.buffer===null?'an undefined number of':r.buffer.toFixed(1)} months of the entered living costs and current debt payment. This assumes assets are accessible; it excludes replacement health coverage after leaving a job.</p>
 <details><summary>${number(p.horizon)}-year financial scenario</summary><p><strong>${money(r.final.net,s.country)}</strong> financial assets minus remaining modeled education/other debt. Home equity and mortgage debt are both excluded.</p>${projectionChart(r,s.country,i)}<div class="table-wrap"><table><thead><tr><th>Year</th><th>Financial assets</th><th>Loan balance</th><th>Assets − loan</th></tr></thead><tbody>${r.points.filter(q=>q.year===0||q.year===r.final.year||q.year%5===0).map(q=>`<tr><td>${q.year}</td><td>${money(q.assets,s.country)}</td><td>${money(q.debt,s.country)}</td><td>${money(q.net,s.country)}</td></tr>`).join('')}</tbody></table></div><p class="hint">Fixed nominal income and spending; ${esc(p.netReturn)}% annual net return, monthly end-of-month contributions, ${esc(p.investPercent)}% of positive surplus invested. Negative surplus reduces assets in full. No PPP conversion of savings.</p></details>
 </article>`;}).join('')}</div>`;renderDecision(x,ps);renderFX(x,ps);}
function renderFX(x,ps){
 const cross=x.scenarios.some(s=>s.country==='CA')&&x.scenarios.some(s=>s.country==='US');
 if(!cross||!ps.every(p=>p.valid)){$('cash-exchange').innerHTML='';return;}
 const rate=Number(fx),valid=fx!==''&&Number.isFinite(rate)&&rate>0&&rate<=10;
 const usd=(amount,s)=>s.country==='CA'?amount/rate:amount;
 $('cash-exchange').innerHTML=`<div class="exchange-panel"><h3>Compare savings in one currency</h3><p>Local purchasing power describes what you can consume. Money you save or move across the border converts at an exchange rate.</p><label>Canadian dollars per US$1<input id="cash-fx" type="number" min="0.01" max="10" step="any" value="${esc(fx)}"></label><p class="hint">Starting point: Bank of Canada 2025 annual average, CA$1.3978 per US$1. Historical reference, not a live conversion quote or a future rate. ${link('https://www.bankofcanada.ca/rates/exchange/annual-average-exchange-rates/','Bank of Canada')}</p>
 ${valid?`<div class="table-wrap"><table><thead><tr><th>Measure · expressed in USD</th>${x.scenarios.map((s,i)=>`<th>${i?'B':'A'} · ${esc(s.place)}</th>`).join('')}</tr></thead><tbody><tr><td>Monthly surplus after living costs and debt</td>${ps.map((p,i)=>`<td>${money(usd(p.left,x.scenarios[i]),'US')}</td>`).join('')}</tr><tr><td>Projected financial assets minus modeled loan</td>${ps.map((p,i)=>`<td>${money(usd(p.final.net,x.scenarios[i]),'US')}<small>Year ${p.final.year}</small></td>`).join('')}</tr></tbody></table></div><p class="hint">CAD amounts ÷ selected exchange rate; USD amounts unchanged. The same rate is held for projections. Conversion fees and FX gains/taxes are excluded. Match projection years and living standards before drawing conclusions.</p>`:'<p class="notice">Enter an exchange rate above zero and no greater than 10.</p>'}</div>`;
 $('cash-fx').addEventListener('change',e=>{fx=e.target.value;renderFX(api.get(),getPlans());});
}
function projectionChart(r,c,i){const min=Math.min(0,...r.points.map(q=>q.net)),max=Math.max(1,...r.points.map(q=>q.net)),range=max-min;const xx=q=>50+q.year/r.final.year*590,yy=q=>140-(q.net-min)/range*118;const path=r.points.map((q,j)=>`${j?'L':'M'}${xx(q).toFixed(1)},${yy(q).toFixed(1)}`).join(' ');return `<svg class="projection-chart" viewBox="0 0 660 180" role="img" aria-label="Financial assets less modeled loan over ${r.final.year} years, ending at ${esc(money(r.final.net,c))}"><line x1="50" x2="640" y1="${140-(0-min)/range*118}" y2="${140-(0-min)/range*118}" stroke="#c6cfd5"/><path d="${path}" fill="none" stroke="${i?'#3e55a1':'#116f6e'}" stroke-width="3"/><text x="50" y="165">Now</text><text x="565" y="165">Year ${r.final.year}</text></svg>`;}
function renderDecision(x,ps){const cases=[['10% lower pay',.9,0,1],['20% lower pay',.8,0,1],['Overhead +5 points',1,5,1],['Living costs +15%',1,0,1.15]];
 const tables=x.scenarios.map((s,i)=>{const r=x.results[i],p=plan(s),pr=ps[i],can=P.variableTaxes(s);if(!r.valid||!pr.valid)return `<article><h3>${i?'B':'A'}</h3><p>Complete the income and budget inputs to run scenarios.</p></article>`;const floor=can?P.solveGross(s,Math.max(0,pr.cashTarget)):null;
 const rows=cases.map(([label,pay,over,living])=>{if(over&&s.kind!=='business')return [label,null,'Only applies to practice revenue.'];if((pay!==1||over)&&!can)return [label,null,s.kind==='net'?'Known take-home; gross taxes cannot be recalculated.':'Fixed tax overrides would need recalculation.'];const rr=pay===1&&!over?r:E.calc({...s,gross:Number(s.gross)*pay,overhead:Number(s.overhead)+over});if(!rr.valid)return [label,null,'Tax/expense inputs unavailable at this income.'];return [label,(rr.cash+Number(p.partnerNet))/12-pr.living*living-pr.debt.payment,''];});
 return `<article><h3>${i?'B':'A'} · ${esc(s.country==='CA'?D.provinces[s.place]:s.place)}</h3><div class="table-wrap"><table><thead><tr><th>Hypothetical change</th><th>Monthly surplus</th></tr></thead><tbody><tr><td>Current scenario</td><td>${money(pr.left,s.country)}</td></tr>${rows.map(([label,v,note])=>`<tr><td>${label}</td><td>${v===null?`<span class="hint">${esc(note)}</span>`:money(v,s.country)}</td></tr>`).join('')}</tbody></table></div><p>${floor===null?'A gross-income break-even estimate needs automatic income taxes and an eligible scenario.':`Approximate ${s.kind==='business'?'gross practice revenue':'salary'} needed to cover this budget and loan payment: <strong>${money(floor,s.country)} / year</strong>.`}</p><p class="hint">Scenarios hold benefit costs and other household income fixed. Overhead remains a percentage of revenue. Moving costs excluded from recurring break-even. These are stress tests, not pay percentiles or forecasts.</p></article>`;}).join('');
 $('decision-results').innerHTML=`<div class="method-grid">${tables}</div><details><summary>How much confidence should I put in this comparison?</summary><div class="table-wrap"><table><thead><tr><th>Layer</th>${x.scenarios.map((s,i)=>`<th>${i?'B':'A'} · ${esc(s.place)}</th>`).join('')}</tr></thead><tbody>${['Pay evidence','Tax completeness','Professional costs','Local prices','Personal budget'].map((key,j)=>`<tr><th>${key}</th>${x.scenarios.map((s,i)=>{const b=B.get(s),r=x.results[i],p=plan(s);return `<td>${esc([s.incomeMode==='benchmark'?b.badge+' · '+b.year:'Your entered amount; not independently verified',r.valid?(s.kind==='net'?'Taxes embedded in entered take-home':P.variableTaxes(s)?'Automatic within the stated 2025 single-filer scope':'Includes your fixed tax totals'):'Incomplete: '+r.missing.join(' '),s.kind==='net'?'Assumed embedded in take-home':s.professionalMode==='employer'?'Employer coverage assumed; confirm the contract':s.professionalMode==='included'?'Included in all-in overhead; historical/model expense assumptions':'Your separate costs; replace allowances with quotes',s.country==='US'?'BEA 2024 area consumption prices':'Analyst bridge: national PPP × local basic basket',p.budgetMode==='modeled'?'Illustrative lifestyle scaled by local prices':'User-selected budget; verify equivalent quality and included costs'][j])}</td>`;}).join('')}</tr>`).join('')}</tbody></table></div><p class="hint">No numerical “confidence score” is assigned. The source population, year and missing inputs matter more than an invented precision rating.</p></details>`;
}
function explorerRows(){const locs=explorer.country==='CA'?Object.keys(D.provinces):Object.keys(D.rpp).filter(x=>x!=='United States');return locs.map(place=>{const s=api.makeScenario(explorer.country,place,explorer.specialty,explorer.basis),b=B.get(s),r=api.estimate(s),power=E.commonPower(s,r);return {place,s,b,r,power,name:s.country==='CA'?D.provinces[place]:place};}).filter(v=>v.name.toLowerCase().includes(explorer.query.toLowerCase())).sort((a,b)=>explorer.sort==='power'?(b.power?.value??-Infinity)-(a.power?.value??-Infinity)||a.name.localeCompare(b.name):explorer.sort==='cash'?(b.r.cash??-Infinity)-(a.r.cash??-Infinity)||a.name.localeCompare(b.name):a.name.localeCompare(b.name));}
function renderExplorer(forms=false){if(forms)$('explorer-controls').innerHTML=`<div class="filters explorer-filters"><label>Country<select data-explorer="country">${options([['US','United States'],['CA','Canada']],explorer.country)}</select></label><label>Specialty<select data-explorer="specialty">${options(B.specialties(explorer.country),explorer.specialty)}</select></label>${explorer.country==='US'?`<label>Pay source<select data-explorer="basis">${options([['auto','AMGA national; BLS state wages if absent'],['national','AMGA national compensation only'],['state','BLS state wages · broader workforce']],explorer.basis)}</select></label>`:''}<label>Order<select data-explorer="sort">${options([['name','Location name'],['power','Estimated spending power'],['cash','Estimated take-home']],explorer.sort)}</select></label><label>Find location<input data-explorer="query" type="search" value="${esc(explorer.query)}" placeholder="Filter locations"></label></div>`;
 const rows=explorerRows(),complete=rows.filter(x=>x.r.valid).length;
 const benchmark=B.get(api.makeScenario(explorer.country,explorer.country==='CA'?'BC':'Oklahoma',explorer.specialty,explorer.basis));
 const sourceNote=explorer.country==='CA'?'<strong>Canada: provincial gross clinical payments.</strong> These medians describe payments before practice expenses and personal tax, across mixed workloads. The estimates below deduct default overhead and taxes as an unincorporated practice. Ontario is underreported; missing medians remain unavailable.':benchmark.quality==='national-group'?'<strong>U.S.: the same national pay benchmark in every state.</strong> AMGA reports compensation for participating medical groups nationally. State selection changes modeled taxes and living costs; it does not turn this figure into a measured state salary.':explorer.basis==='national'?'<strong>U.S.: national compensation source selected.</strong> No AMGA median is available for this specialty. Select another source or enter your own income in the comparison above.':'<strong>U.S.: state wages for a broader workforce.</strong> BLS wage medians include trainees and mixed career stages, exclude self-employed physicians, and omit some compensation. They do not estimate attending-only salaries.';
 $('explorer-table').innerHTML=`<p class="notice neutral explorer-source-note">${sourceNote}</p><p class="hint">${complete} of ${rows.length} shown locations have a complete automatic estimate for this source and specialty. Take-home means income after modeled practice costs, taxes and personal insurance, before household spending. These estimates assume employee salary or an unincorporated practice, single health coverage, default overhead, no NYC resident tax and no personal budget. U.S. prices use the state index; Canada uses the named reference city. Local taxes and missing medians can block a row. Sorting incomplete coverage is not a ranking of all locations.</p><div class="table-wrap explorer-scroll"><table><thead><tr><th>Location</th><th>Published median & income type</th><th>Source & year</th><th>Estimated take-home / year</th><th>Estimated spending power / year</th><th>Load comparison</th></tr></thead><tbody>${rows.map(v=>`<tr><td><strong>${esc(v.name)}</strong><small>${esc(v.power?.area??v.s.priceArea)}</small></td><td>${money(v.b.value,v.s.country)}<small>${v.b.quality==='clinical-gross'?'Provincial gross clinical payments':v.b.quality==='national-group'?'National medical-group compensation':v.b.quality==='broad-state-wage'?'State wages · broader workforce':'No numeric median available'}</small></td><td>${link(v.b.url,v.b.badge)}<small>${esc(v.b.year)}</small></td><td>${v.r.valid?money(v.r.cash,v.s.country):`<span class="hint">${esc(v.r.missing.join(' '))}</span>`}</td><td>${intl(v.power?.value)}</td><td><div class="row-actions"><a href="#quick-controls" data-explore-load="0" data-place="${esc(v.place)}" aria-label="Use ${esc(v.name)} as location A">Use as A</a><a href="#quick-controls" data-explore-load="1" data-place="${esc(v.place)}" aria-label="Use ${esc(v.name)} as location B">Use as B</a></div></td></tr>`).join('')||'<tr><td colspan="6">No matching locations.</td></tr>'}</tbody></table></div><p class="hint">Spending power uses a common consumption unit (I$), not currency you receive. Load a location into A or B to review its income source, expense assumptions and any missing tax inputs.</p><button id="export-explorer">Download these data as CSV</button>`;
}
function download(name,type,content){const url=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function csv(rows){return rows.map(r=>r.map(v=>'"'+String(v??'').replaceAll('"','""')+'"').join(',')).join('\r\n');}
function method(){const el=$('method-content');el.insertAdjacentHTML('beforeend',`<details><summary>Housing, debt, time and financial projection method</summary><div class="method-grid"><article><h3>Housing references</h3><p>U.S.: ${L.housingUS.length} state/area records from the HUD FY2025 studio-to-four-bedroom schedule, with April 28 revisions applied. Cross-state areas occur once per relevant state. These are rent standards, not observed state medians. Major utilities are included. Canada: ${L.housingCA.length} CMHC October 2025 two-bedroom city references, including seven new-tenant averages. Other city rows use all-unit averages and may understate newcomer rent. No province rent is fabricated where absent.</p><p>These rents are optional inputs to a cash budget. They do not replace the BEA/MBM purchasing-power indexes and are not claimed to be the same statistical measure across countries. Use local quotes for equivalent housing. ${link(L.sources[0][1],'HUD schedule')} · ${link(L.sources[1][1],'HUD revisions')} · ${link(L.sources[2][1],'HUD definitions')} · ${link(L.sources[3][1],'CMHC')}</p></article><article><h3>Monthly cash and loan payments</h3><p>Household net income ÷ 12 − living budget − current loan payment = monthly surplus. Adding other household income does not change the physician’s modeled tax filing status. Loan payment = principal × monthly rate ÷ [1 − (1 + monthly rate)^(−months)]; a zero-rate loan divides principal by months. Extra payments reduce balance and interest monthly. The AAMC debt example is optional and applies to indebted graduates, not all doctors.</p><p>Home ownership uses the same payment formula; Canadian mortgage rates use a semiannual-to-monthly conversion. Ownership cash costs include entered property tax, insurance, maintenance and fees. The down payment is a separately funded upfront amount. ${link(L.sources[4][1],'AAMC debt evidence')}</p></article><article><h3>Time, resilience and projections</h3><p>Cash per committed hour = physician cash ÷ [(work hours + commute hours) × weeks]. Work hours do not estimate a different salary. Break-even income is found by repeatedly recalculating taxes and expenses until cash covers the entered budget and debt. Fixed tax overrides disable income stress tests and break-even, except an explicit zero local-tax override.</p><p>Financial projections compound assets monthly at your hypothetical net return, then add the selected share of surplus. Debt payments stop when repaid. The model holds nominal pay and living costs fixed; it does not forecast markets, raises, inflation or tax changes. It does not convert savings using PPP. Home equity, mortgage debt and employer pensions are excluded.</p></article><article><h3>Additional 2025 state coverage</h3><p>Eight states now have added state-income-tax calculations: ${Object.keys(L.taxes).join(', ')}. Colorado includes the modeled employee FAMLI contribution. Michigan, Kentucky and Colorado still require local-tax totals. All U.S. business scenarios require applicable local/business taxes. Low-income credits and special deductions remain outside the model.</p><p>The tax snapshot remains 2025 even though the site was reviewed in September 2026. Pay and price series carry their own data years. Use a known after-tax offer or entered totals to reflect a different year or filing status.</p></article></div></details><details><summary>Additional primary sources · September 2026 review</summary><ul class="sources">${L.sources.map(([t,u])=>`<li>${link(u,t)}</li>`).join('')}</ul></details>`);}
function init(x){api=x;document.addEventListener('input',e=>{const el=e.target;if(el.matches('input[data-plan-side]')){const p=plan(api.get().scenarios[Number(el.dataset.planSide)]);p[el.dataset.planKey]=el.value;if(el.dataset.planKey==='rent')p.rentNote='Custom rent; verify a local quote and utility coverage.';renderResults();}if(el.matches('input[data-explorer]')){explorer.query=el.value;renderExplorer();}});
 document.addEventListener('change',e=>{const el=e.target;if(el.matches('select[data-plan-side]')){const p=plan(api.get().scenarios[Number(el.dataset.planSide)]);p[el.dataset.planKey]=el.value;renderForms();renderResults();}if(el.matches('select[data-explorer]')){explorer[el.dataset.explorer]=el.value;if(el.dataset.explorer==='country')explorer.specialty=B.normalize(explorer.specialty,explorer.country);renderExplorer(true);}});
 document.addEventListener('click',e=>{let el=e.target.closest('[data-load-rent]');if(el){const s=api.get().scenarios[Number(el.dataset.loadRent)],p=plan(s),r=housingReference(s,p);if(r){p.rent=r.amount;p.rentNote=r.note;if(s.country==='US'){p.utilities=100;p.rentNote+=' The utilities field was reset to a US$100 phone/internet allowance; edit it for your plan.';}renderForms();renderResults();}return;}
 el=e.target.closest('[data-load-debt]');if(el){plan(api.get().scenarios[Number(el.dataset.loadDebt)]).debt=L.debtMedian;renderForms();renderResults();return;}
 el=e.target.closest('[data-explore-load]');if(el){api.load(Number(el.dataset.exploreLoad),api.makeScenario(explorer.country,el.dataset.place,explorer.specialty,explorer.basis));return;}
 if(e.target.closest('#export-explorer')){const rows=explorerRows();download('physician-pay-locations.csv','text/csv;charset=utf-8',csv([['Country','Location','Specialty','Currency','Median','Income_type','Evidence','Year','Cash_after_tax_costs','Modeled_I$_power','Price_area','Missing_inputs','Source'],...rows.map(v=>[v.s.country,v.name,explorer.specialty,v.s.country==='CA'?'CAD':'USD',v.b.value,v.b.kind,v.b.badge,v.b.year,v.r.cash,v.power?.value,v.power?.area,v.r.missing.join('; '),v.b.url])]));}
 if(e.target.closest('#print-comparison'))window.print();
 });}
root.PayLayers={settings:()=>({fx}),restore:v=>{fx=String(v&&Number(v.fx)>0&&Number(v.fx)<=10?v.fx:L.fxCADperUSD);},init,renderForms,renderResults,renderExplorer,method,plan,housingReference};
})(globalThis);
